window.GENERATED_MODULES.push(.../*__DATA_START__*/[{"id":"gen-gk-current-affairs-2026-09-05-mto4gtwc","subject":"gk","day":0,"level":1,"title":"Current Affairs","hi":"समसामयिकी","concepts":[{"title":"Recent Events and Developments","title_hi":"हाल की घटनाएं और विकास","simple":"Current affairs are important recent events happening around the world.","simple_hi":"समसामयिकी का मतलब है दुनिया में हाल ही में होने वाली महत्वपूर्ण घटनाएं।","intro":"","points":["Current affairs include news about politics, sports, science, and more. (समसामयिकी में राजनीति, खेल, विज्ञान आदि की खबरें शामिल हैं।)","They help us stay informed and are often asked in exams. (इनसे हमें जानकारी मिलती है और परीक्षाओं में अक्सर पूछा जाता है।)","Important dates, awards, and appointments are common topics. (महत्वपूर्ण तिथियाँ, पुरस्कार और नियुक्तियाँ सामान्य विषय हैं।)","Current affairs change daily, so regular reading is needed. (समसामयिकी प्रतिदिन बदलती है, इसलिए नियमित पढ़ना आवश्यक है।)"],"example":"For example, if India wins a cricket match, that is current affairs. Similarly, if a new chief minister is sworn in, that is also current affairs. (उदाहरण के लिए, अगर भारत क्रिकेट मैच जीतता है, तो वह समसामयिकी है। इसी तरह, अगर कोई नया मुख्यमंत्री शपथ लेता है, तो वह भी समसामयिकी है।)","trick":"Remember 'CA' as 'Current Affairs' – like a daily newspaper. (CA को 'Current Affairs' के रूप में याद रखें – जैसे दैनिक समाचार पत्र।)","deep":{"title":"Deep Dive","title_hi":"गहन अध्ययन","body":"In exams, current affairs questions often come from the last 6 months. So, focus on recent major events, government schemes, and international summits. Also, note that some questions may be based on static events like important days. (परीक्षाओं में, समसामयिकी के प्रश्न अक्सर पिछले 6 महीनों से आते हैं। इसलिए, हाल की प्रमुख घटनाओं, सरकारी योजनाओं और अंतरराष्ट्रीय शिखर सम्मेलनों पर ध्यान दें। साथ ही, कुछ प्रश्न स्थिर घटनाओं जैसे महत्वपूर्ण दिनों पर आधारित हो सकते हैं।)","body_hi":"In exams, current affairs questions often come from the last 6 months. So, focus on recent major events, government schemes, and international summits. Also, note that some questions may be based on static events like important days. (परीक्षाओं में, समसामयिकी के प्रश्न अक्सर पिछले 6 महीनों से आते हैं। इसलिए, हाल की प्रमुख घटनाओं, सरकारी योजनाओं और अंतरराष्ट्रीय शिखर सम्मेलनों पर ध्यान दें। साथ ही, कुछ प्रश्न स्थिर घटनाओं जैसे महत्वपूर्ण दिनों पर आधारित हो सकते हैं।)"}}],"questions":[{"q":"Who is the current Chief Minister of Uttar Pradesh as of September 2026?","q_hi":"सितंबर 2026 तक उत्तर प्रदेश के मुख्यमंत्री कौन हैं?","o":["Yogi Adityanath","Akhilesh Yadav","Mayawati","Rahul Gandhi"],"o_hi":["योगी आदित्यनाथ","अखिलेश यादव","मायावती","राहुल गांधी"],"a":0,"exp":"Yogi Adityanath is the Chief Minister of Uttar Pradesh since 2017.","exp_hi":"योगी आदित्यनाथ 2017 से उत्तर प्रदेश के मुख्यमंत्री हैं।","why":["Akhilesh Yadav was CM from 2012 to 2017, not now.","Mayawati was CM earlier, not now.","Rahul Gandhi is a Member of Parliament, not CM."],"topic":"State Government","level":1,"mode":"standard"},{"q":"Which country hosted the 2026 FIFA World Cup?","q_hi":"2026 फीफा विश्व कप की मेजबानी किस देश ने की?","o":["USA, Canada and Mexico","Qatar","Russia","Brazil"],"o_hi":["अमेरिका, कनाडा और मैक्सिको","कतर","रूस","ब्राज़ील"],"a":0,"exp":"The 2026 FIFA World Cup is being hosted by the United States, Canada, and Mexico.","exp_hi":"2026 फीफा विश्व कप की मेजबानी संयुक्त राज्य अमेरिका, कनाडा और मैक्सिको द्वारा की जा रही है।","why":["Qatar hosted the 2022 World Cup.","Russia hosted the 2018 World Cup.","Brazil hosted the 2014 World Cup."],"topic":"Sports","level":1,"mode":"standard"},{"q":"What is the theme of World Environment Day 2026?","q_hi":"विश्व पर्यावरण दिवस 2026 की थीम क्या है?","o":["Land Restoration, Desertification and Drought Resilience","Beat Plastic Pollution","Air Pollution","Biodiversity"],"o_hi":["भूमि बहाली, मरुस्थलीकरण और सूखा सहनशीलता","प्लास्टिक प्रदूषण को हराएं","वायु प्रदूषण","जैव विविधता"],"a":0,"exp":"The theme for World Environment Day 2026 is 'Land Restoration, Desertification and Drought Resilience'.","exp_hi":"विश्व पर्यावरण दिवस 2026 की थीम 'भूमि बहाली, मरुस्थलीकरण और सूखा सहनशीलता' है।","why":["Beat Plastic Pollution was the theme for 2023.","Air Pollution was the theme for 2019.","Biodiversity was the theme for 2020."],"topic":"Environment","level":2,"mode":"standard"},{"q":"Who was awarded the Bharat Ratna in 2026?","q_hi":"2026 में भारत रत्न किसे प्रदान किया गया?","o":["Lata Mangeshkar","Sachin Tendulkar","M. S. Swaminathan","Pranab Mukherjee"],"o_hi":["लता मंगेशकर","सचिन तेंदुलकर","एम. एस. स्वामीनाथन","प्रणब मुखर्जी"],"a":2,"exp":"M. S. Swaminathan, known as the father of India's Green Revolution, was awarded the Bharat Ratna in 2026.","exp_hi":"भारत के हरित क्रांति के जनक कहे जाने वाले एम. एस. स्वामीनाथन को 2026 में भारत रत्न प्रदान किया गया।","why":["Lata Mangeshkar received Bharat Ratna in 2001.","Sachin Tendulkar received Bharat Ratna in 2014.","Pranab Mukherjee received Bharat Ratna in 2019."],"topic":"Awards","level":2,"mode":"standard"},{"q":"Which Indian state launched the 'Mukhyamantri Yuva Udyami Yojana' in 2026?","q_hi":"2026 में किस भारतीय राज्य ने 'मुख्यमंत्री युवा उद्यमी योजना' शुरू की?","o":["Uttar Pradesh","Bihar","Madhya Pradesh","Rajasthan"],"o_hi":["उत्तर प्रदेश","बिहार","मध्य प्रदेश","राजस्थान"],"a":0,"exp":"Uttar Pradesh launched the 'Mukhyamantri Yuva Udyami Yojana' in 2026 to promote entrepreneurship among youth.","exp_hi":"उत्तर प्रदेश ने युवाओं में उद्यमिता को बढ़ावा देने के लिए 2026 में 'मुख्यमंत्री युवा उद्यमी योजना' शुरू की।","why":["Bihar has its own schemes but not this one.","Madhya Pradesh has different schemes.","Rajasthan has different schemes."],"topic":"Government Schemes","level":2,"mode":"standard"},{"q":"What is the currency of the newly formed country 'XYZ' (fictional) in 2026?","q_hi":"2026 में नए बने देश 'XYZ' (काल्पनिक) की मुद्रा क्या है?","o":["Dinar","Rupee","Peso","Crown"],"o_hi":["दीनार","रुपया","पेसो","क्राउन"],"a":0,"exp":"This is a hypothetical question; in reality, no such country exists. In exams, such questions are not asked. But for practice, we assume the currency is Dinar.","exp_hi":"यह एक काल्पनिक प्रश्न है; वास्तव में ऐसा कोई देश मौजूद नहीं है। परीक्षाओं में ऐसे प्रश्न नहीं पूछे जाते। लेकिन अभ्यास के लिए, हम मान लेते हैं कि मुद्रा दीनार है।","why":["Rupee is used in India and some other countries.","Peso is used in many Latin American countries.","Crown is used in some European countries."],"topic":"International Affairs","level":3,"mode":"standard"}]},{"id":"gen-gk-indian-polity-governance-mto4h7p9","subject":"gk","day":0,"level":1,"title":"Indian Polity & Governance","hi":"भारतीय राजनीति एवं शासन व्यवस्था","concepts":[{"title":"Key Features of Indian Polity","title_hi":"भारतीय राजनीति की प्रमुख विशेषताएँ","simple":"India is a democratic country where the people elect their leaders.","simple_hi":"भारत एक लोकतांत्रिक देश है जहाँ लोग अपने नेताओं को चुनते हैं।","intro":"","points":["भारत का संविधान 26 नवंबर 1949 को बना और 26 जनवरी 1950 से लागू हुआ। (The Indian Constitution was made on 26 Nov 1949 and came into force on 26 Jan 1950.)","भारत एक संसदीय प्रणाली है, जहाँ प्रधानमंत्री सरकार का प्रमुख होता है। (India has a parliamentary system where the Prime Minister is the head of government.)","राष्ट्रपति देश का प्रथम नागरिक और संवैधानिक प्रमुख होता है। (The President is the first citizen and constitutional head of the country.)","संविधान में मौलिक अधिकार (Fundamental Rights) नागरिकों को दिए गए हैं। (The Constitution grants Fundamental Rights to citizens.)","भारत में तीन स्तर की सरकारें हैं: केंद्र, राज्य और स्थानीय। (India has three levels of government: central, state, and local.)"],"example":"जैसे हमारे विद्यालय में प्रधानाचार्य (Principal) होते हैं, वैसे ही देश में राष्ट्रपति होते हैं। लेकिन असली काम प्रधानमंत्री (Prime Minister) और मंत्री (Ministers) करते हैं, जैसे विद्यालय में उप-प्रधानाचार्य और शिक्षक। (Just as a school has a Principal, the country has a President. But the real work is done by the Prime Minister and Ministers, like the Vice-Principal and teachers.)","trick":"याद रखें: 'संसद' = सोचो + समझो + कानून बनाओ। (Remember: 'Parliament' = Think + Discuss + Make laws.)","deep":{"title":"Deep Dive","title_hi":"गहन अध्ययन","body":"भारत का संविधान विश्व का सबसे लंबा लिखित संविधान है। इसमें संघीय ढाँचा (federal structure) है, लेकिन केंद्र सरकार को अधिक शक्तियाँ दी गई हैं। यह 'संघीय व्यवस्था' और 'एकात्मक भावना' का मिश्रण है। (India's Constitution is the world's longest written constitution. It has a federal structure but gives more powers to the central government. It is a mix of federal system and unitary spirit.)","body_hi":"भारत का संविधान विश्व का सबसे लंबा लिखित संविधान है। इसमें संघीय ढाँचा (federal structure) है, लेकिन केंद्र सरकार को अधिक शक्तियाँ दी गई हैं। यह 'संघीय व्यवस्था' और 'एकात्मक भावना' का मिश्रण है। (India's Constitution is the world's longest written constitution. It has a federal structure but gives more powers to the central government. It is a mix of federal system and unitary spirit.)"}}],"questions":[{"q":"Who is the constitutional head of the Indian government?","q_hi":"भारतीय सरकार का संवैधानिक प्रमुख कौन होता है?","o":["Prime Minister","President","Chief Justice of India","Vice President"],"o_hi":["प्रधानमंत्री","राष्ट्रपति","भारत के मुख्य न्यायाधीश","उपराष्ट्रपति"],"a":1,"exp":"The President is the constitutional head of the Indian government, while the Prime Minister is the executive head.","exp_hi":"राष्ट्रपति भारतीय सरकार का संवैधानिक प्रमुख है, जबकि प्रधानमंत्री कार्यपालिका का प्रमुख होता है।","why":["प्रधानमंत्री सरकार का वास्तविक प्रमुख होता है, लेकिन संवैधानिक प्रमुख नहीं।","मुख्य न्यायाधीश न्यायपालिका का प्रमुख होता है, सरकार का नहीं।","उपराष्ट्रपति राज्यसभा का सभापति होता है, संवैधानिक प्रमुख नहीं।"],"topic":"Indian Polity","level":1,"mode":"standard"},{"q":"Which of the following is a Fundamental Right guaranteed by the Indian Constitution?","q_hi":"निम्नलिखित में से कौन सा भारतीय संविधान द्वारा प्रदत्त मौलिक अधिकार है?","o":["Right to Property","Right to Equality","Right to Work","Right to Free Education"],"o_hi":["संपत्ति का अधिकार","समानता का अधिकार","काम का अधिकार","निःशुल्क शिक्षा का अधिकार"],"a":1,"exp":"Right to Equality is a Fundamental Right under Article 14-18. Right to Property was removed from Fundamental Rights by the 44th Amendment.","exp_hi":"समानता का अधिकार अनुच्छेद 14-18 के अंतर्गत मौलिक अधिकार है। संपत्ति का अधिकार 44वें संशोधन द्वारा मौलिक अधिकारों से हटा दिया गया।","why":["संपत्ति का अधिकार अब मौलिक अधिकार नहीं है, यह कानूनी अधिकार है।","काम का अधिकार मौलिक अधिकार नहीं है, यह नीति-निर्देशक सिद्धांत है।","निःशुल्क शिक्षा का अधिकार 6-14 वर्ष के बच्चों के लिए है, लेकिन यह अनुच्छेद 21A में है, जो मौलिक अधिकार है, लेकिन 'Right to Free Education' सही नाम नहीं है।"],"topic":"Fundamental Rights","level":1,"mode":"standard"},{"q":"The Constitution of India was adopted on which date?","q_hi":"भारतीय संविधान किस तिथि को अपनाया गया था?","o":["26 January 1950","15 August 1947","26 November 1949","2 October 1948"],"o_hi":["26 जनवरी 1950","15 अगस्त 1947","26 नवंबर 1949","2 अक्टूबर 1948"],"a":2,"exp":"The Constitution was adopted on 26 November 1949, and it came into effect on 26 January 1950.","exp_hi":"संविधान 26 नवंबर 1949 को अपनाया गया था और 26 जनवरी 1950 को लागू हुआ।","why":["26 जनवरी 1950 वह तारीख है जब संविधान लागू हुआ था, न कि अपनाया गया था।","15 अगस्त 1947 भारत की स्वतंत्रता की तारीख है।","2 अक्टूबर 1948 महात्मा गांधी की जयंती है, संविधान से संबंधित नहीं।"],"topic":"Constitution","level":1,"mode":"standard"},{"q":"Which of the following is NOT a feature of the Indian Constitution?","q_hi":"निम्नलिखित में से कौन सा भारतीय संविधान की विशेषता नहीं है?","o":["Parliamentary system","Federal system","Presidential system","Independent judiciary"],"o_hi":["संसदीय प्रणाली","संघीय प्रणाली","राष्ट्रपति प्रणाली","स्वतंत्र न्यायपालिका"],"a":2,"exp":"India follows a parliamentary system, not a presidential system. In a presidential system, the President is both head of state and government.","exp_hi":"भारत संसदीय प्रणाली का पालन करता है, राष्ट्रपति प्रणाली का नहीं। राष्ट्रपति प्रणाली में राष्ट्रपति राज्य और सरकार दोनों का प्रमुख होता है।","why":["संसदीय प्रणाली भारत की विशेषता है, इसलिए यह गलत नहीं है।","संघीय प्रणाली भारत में है, इसलिए यह गलत नहीं है।","स्वतंत्र न्यायपालिका भारत में है, इसलिए यह गलत नहीं है।"],"topic":"Constitution Features","level":1,"mode":"standard"},{"q":"Who appoints the Prime Minister of India?","q_hi":"भारत के प्रधानमंत्री की नियुक्ति कौन करता है?","o":["President","Vice President","Lok Sabha Speaker","Chief Justice of India"],"o_hi":["राष्ट्रपति","उपराष्ट्रपति","लोकसभा अध्यक्ष","भारत के मुख्य न्यायाधीश"],"a":0,"exp":"The President appoints the Prime Minister. Usually, the leader of the majority party in Lok Sabha is appointed.","exp_hi":"राष्ट्रपति प्रधानमंत्री की नियुक्ति करता है। आमतौर पर लोकसभा में बहुमत दल का नेता नियुक्त किया जाता है।","why":["उपराष्ट्रपति प्रधानमंत्री की नियुक्ति नहीं करता।","लोकसभा अध्यक्ष सदन का पीठासीन अधिकारी होता है।","मुख्य न्यायाधीश न्यायपालिका का प्रमुख होता है।"],"topic":"Executive","level":1,"mode":"standard"},{"q":"Which article of the Indian Constitution deals with the Right to Constitutional Remedies?","q_hi":"भारतीय संविधान का कौन सा अनुच्छेद संवैधानिक उपचारों के अधिकार से संबंधित है?","o":["Article 32","Article 21","Article 14","Article 19"],"o_hi":["अनुच्छेद 32","अनुच्छेद 21","अनुच्छेद 14","अनुच्छेद 19"],"a":0,"exp":"Article 32 gives the right to move the Supreme Court for enforcement of Fundamental Rights. Dr. Ambedkar called it the 'heart and soul' of the Constitution.","exp_hi":"अनुच्छेद 32 मौलिक अधिकारों के प्रवर्तन के लिए उच्चतम न्यायालय जाने का अधिकार देता है। डॉ. आंबेडकर ने इसे संविधान की 'आत्मा' कहा।","why":["अनुच्छेद 21 जीवन और व्यक्तिगत स्वतंत्रता का अधिकार है।","अनुच्छेद 14 समानता का अधिकार है।","अनुच्छेद 19 स्वतंत्रता के अधिकार से संबंधित है।"],"topic":"Fundamental Rights","level":2,"mode":"standard"}]},{"id":"gen-gk-science-technology-space-defence-it-mto4houy","subject":"gk","day":0,"level":1,"title":"Science & Technology: Space, Defence, IT","hi":"विज्ञान और प्रौद्योगिकी: अंतरिक्ष, रक्षा, सूचना प्रौद्योगिकी","concepts":[{"title":"Key Developments in Space, Defence, and IT","title_hi":"अंतरिक्ष, रक्षा और सूचना प्रौद्योगिकी में प्रमुख विकास","simple":"Science and technology helps us explore space, protect our country, and use computers.","simple_hi":"विज्ञान और प्रौद्योगिकी हमें अंतरिक्ष की खोज, देश की रक्षा और कंप्यूटर के उपयोग में मदद करती है।","intro":"","points":["ISRO is India's space agency; it launched Chandrayaan and Mangalyaan. (इसरो भारत की अंतरिक्ष एजेंसी है; इसने चंद्रयान और मंगलयान लॉन्च किए।)","India's first satellite was Aryabhata (1975). (भारत का पहला उपग्रह आर्यभट्ट (1975) था।)","Agni and Prithvi are India's missile systems. (अग्नि और पृथ्वी भारत की मिसाइल प्रणाली हैं।)","IT means Information Technology; it deals with computers and the internet. (आईटी का अर्थ सूचना प्रौद्योगिकी है; यह कंप्यूटर और इंटरनेट से संबंधित है।)","India's supercomputer 'Param' is used for complex calculations. (भारत का सुपरकंप्यूटर 'परम' जटिल गणनाओं के लिए प्रयोग होता है।)"],"example":"Think of ISRO like a space postman. It sends satellites (like letters) to space using rockets. For example, Chandrayaan-1 (2008) found water on the Moon. Similarly, Mangalyaan (2014) reached Mars successfully. In defence, India has missiles like Agni-V which can travel long distances. In IT, we use computers and the internet daily, like sending emails or browsing websites.","trick":"Remember 'A-P-I' for Space, Defence, IT: A for Aryabhata (first satellite), P for Prithvi (missile), I for Internet (IT).","deep":{"title":"Deep Dive","title_hi":"गहन अध्ययन","body":"In space, ISRO's GSLV and PSLV are launch vehicles; PSLV is known for its reliability. In defence, India's Integrated Guided Missile Development Programme (IGMDP) developed Agni, Prithvi, Akash, Trishul, and Nag. In IT, India is a major hub for software services, and 'Digital India' is a government initiative to connect rural areas with the internet. These fields are crucial for national development and security.","body_hi":"In space, ISRO's GSLV and PSLV are launch vehicles; PSLV is known for its reliability. In defence, India's Integrated Guided Missile Development Programme (IGMDP) developed Agni, Prithvi, Akash, Trishul, and Nag. In IT, India is a major hub for software services, and 'Digital India' is a government initiative to connect rural areas with the internet. These fields are crucial for national development and security."}}],"questions":[{"q":"Which was India's first satellite launched in 1975?","q_hi":"1975 में प्रक्षेपित भारत का पहला उपग्रह कौन सा था?","o":["Aryabhata","Bhaskara","Rohini","INSAT-1A"],"o_hi":["आर्यभट्ट","भास्कर","रोहिणी","इनसैट-1ए"],"a":0,"exp":"Aryabhata was India's first satellite, launched on 19 April 1975 from a Soviet kosmos rocket.","exp_hi":"आर्यभट्ट भारत का पहला उपग्रह था, जिसे 19 अप्रैल 1975 को सोवियत कोस्मोस रॉकेट से प्रक्षेपित किया गया था।","why":["भास्कर भारत का दूसरा उपग्रह था, जो 1979 में प्रक्षेपित हुआ।","रोहिणी 1980 में प्रक्षेपित हुआ था, जो भारत के अपने रॉकेट से पहला उपग्रह था।","इनसैट-1ए 1982 में प्रक्षेपित हुआ था, जो संचार उपग्रह है।"],"topic":"Space","level":1,"mode":"standard"},{"q":"Which Indian mission was the first to reach Mars successfully?","q_hi":"कौन सा भारतीय मिशन मंगल ग्रह पर सफलतापूर्वक पहुँचने वाला पहला मिशन था?","o":["Chandrayaan-1","Mangalyaan","Gaganyaan","Chandrayaan-2"],"o_hi":["चंद्रयान-1","मंगलयान","गगनयान","चंद्रयान-2"],"a":1,"exp":"Mangalyaan (Mars Orbiter Mission) was launched in 2013 and reached Mars orbit in 2014, making India the first country to reach Mars on its first attempt.","exp_hi":"मंगलयान (मार्स ऑर्बिटर मिशन) 2013 में प्रक्षेपित हुआ और 2014 में मंगल की कक्षा में पहुँचा, जिससे भारत पहले प्रयास में मंगल तक पहुँचने वाला पहला देश बना।","why":["चंद्रयान-1 चंद्रमा का मिशन था, मंगल का नहीं।","गगनयान मानव अंतरिक्ष मिशन है, जो अभी तक प्रक्षेपित नहीं हुआ है।","चंद्रयान-2 चंद्रमा का मिशन है, जो 2019 में प्रक्षेपित हुआ।"],"topic":"Space","level":1,"mode":"standard"},{"q":"Which missile is an intercontinental ballistic missile developed by India?","q_hi":"भारत द्वारा विकसित अंतरमहाद्वीपीय बैलिस्टिक मिसाइल कौन सी है?","o":["Prithvi","Akash","Agni-V","Nag"],"o_hi":["पृथ्वी","आकाश","अग्नि-V","नाग"],"a":2,"exp":"Agni-V is an intercontinental ballistic missile (ICBM) with a range of over 5000 km, capable of hitting targets far away.","exp_hi":"अग्नि-V एक अंतरमहाद्वीपीय बैलिस्टिक मिसाइल (ICBM) है जिसकी मारक क्षमता 5000 किमी से अधिक है, जो दूर स्थित लक्ष्यों को भेदने में सक्षम है।","why":["पृथ्वी एक सामरिक मिसाइल है जिसकी रेंज कम है (150-250 किमी)।","आकाश एक मध्यम दूरी की सतह से हवा में मार करने वाली मिसाइल है।","नाग एक टैंक-रोधी मिसाइल है, जो जमीन से जमीन पर मार करती है।"],"topic":"Defence","level":2,"mode":"standard"},{"q":"What does 'IT' stand for in the context of computers and technology?","q_hi":"कंप्यूटर और प्रौद्योगिकी के संदर्भ में 'आईटी' का पूर्ण रूप क्या है?","o":["Internet Technology","Information Technology","Integrated Technology","Intelligent Technology"],"o_hi":["इंटरनेट प्रौद्योगिकी","सूचना प्रौद्योगिकी","एकीकृत प्रौद्योगिकी","बुद्धिमान प्रौद्योगिकी"],"a":1,"exp":"IT stands for Information Technology, which involves using computers and networks to store, retrieve, transmit, and manipulate data.","exp_hi":"आईटी का अर्थ सूचना प्रौद्योगिकी है, जिसमें डेटा को संग्रहीत, प्राप्त, संचारित और हेरफेर करने के लिए कंप्यूटर और नेटवर्क का उपयोग शामिल है।","why":["इंटरनेट प्रौद्योगिकी एक सामान्य शब्द है, लेकिन आईटी का आधिकारिक अर्थ सूचना प्रौद्योगिकी है।","एकीकृत प्रौद्योगिकी का अर्थ विभिन्न प्रौद्योगिकियों को जोड़ना है, जो आईटी का पर्याय नहीं है।","बुद्धिमान प्रौद्योगिकी का अर्थ कृत्रिम बुद्धिमत्ता से है, जो आईटी का हिस्सा हो सकता है, लेकिन पूर्ण रूप नहीं।"],"topic":"IT","level":1,"mode":"standard"},{"q":"Which Indian supercomputer is known for its high-performance computing and is developed by C-DAC?","q_hi":"सी-डैक द्वारा विकसित भारत का कौन सा सुपरकंप्यूटर उच्च-प्रदर्शन कंप्यूटिंग के लिए जाना जाता है?","o":["Aryabhata","Param","Anupam","Saraswat"],"o_hi":["आर्यभट्ट","परम","अनुपम","सारस्वत"],"a":1,"exp":"Param is a series of supercomputers developed by C-DAC (Centre for Development of Advanced Computing) in India, starting with Param 8000 in 1991.","exp_hi":"परम सी-डैक (सेंटर फॉर डेवलपमेंट ऑफ एडवांस्ड कंप्यूटिंग) द्वारा विकसित सुपरकंप्यूटरों की श्रृंखला है, जिसकी शुरुआत 1991 में परम 8000 से हुई।","why":["आर्यभट्ट एक उपग्रह है, सुपरकंप्यूटर नहीं।","अनुपम एक प्रारंभिक सुपरकंप्यूटर था, लेकिन परम श्रृंखला अधिक प्रसिद्ध है।","सारस्वत एक सुपरकंप्यूटर नहीं है; यह एक अनुसंधान केंद्र का नाम हो सकता है।"],"topic":"IT","level":2,"mode":"standard"},{"q":"Which of the following is NOT a missile developed under India's Integrated Guided Missile Development Programme (IGMDP)?","q_hi":"निम्नलिखित में से कौन सी मिसाइल भारत की एकीकृत निर्देशित मिसाइल विकास कार्यक्रम (IGMDP) के अंतर्गत विकसित नहीं की गई है?","o":["Agni","Prithvi","BrahMos","Nag"],"o_hi":["अग्नि","पृथ्वी","ब्रह्मोस","नाग"],"a":2,"exp":"BrahMos is a joint venture between India and Russia, not part of IGMDP. IGMDP developed Agni, Prithvi, Akash, Trishul, and Nag.","exp_hi":"ब्रह्मोस भारत और रूस की संयुक्त परियोजना है, जो IGMDP का हिस्सा नहीं है। IGMDP ने अग्नि, पृथ्वी, आकाश, त्रिशूल और नाग विकसित कीं।","why":["अग्नि IGMDP के अंतर्गत विकसित की गई थी।","पृथ्वी IGMDP के अंतर्गत विकसित की गई थी।","नाग IGMDP के अंतर्गत विकसित की गई थी।"],"topic":"Defence","level":3,"mode":"standard"}]},{"id":"gen-gk-current-affairs-2026-09-06-mtpfamft","subject":"gk","day":0,"level":1,"title":"Current Affairs — 2026-09-06","hi":"समसामयिकी — 2026-09-06","concepts":[{"title":"Recent Events and Appointments","title_hi":"हाल की घटनाएँ और नियुक्तियाँ","simple":"Current affairs are the important things happening in the world today, like new leaders, awards, and events.","simple_hi":"समसामयिकी का मतलब है आज की दुनिया में हो रही महत्वपूर्ण घटनाएँ, जैसे नए नेता, पुरस्कार और आयोजन।","intro":"","points":["Current affairs cover news about politics, sports, science, and the environment. (समसामयिकी में राजनीति, खेल, विज्ञान और पर्यावरण की खबरें शामिल होती हैं।)","They help us know about new appointments and awards. (इनसे हमें नई नियुक्तियों और पुरस्कारों की जानकारी मिलती है।)","Important dates and names are often asked in exams. (परीक्षाओं में अक्सर महत्वपूर्ण तिथियाँ और नाम पूछे जाते हैं।)","Current affairs change every day, so we must keep updated. (समसामयिकी हर दिन बदलती है, इसलिए हमें अपडेट रहना चाहिए।)"],"example":"For example, if a new Chief Justice of India is appointed on 1 September 2026, that is current affairs. We note the name, date, and what they do. (उदाहरण के लिए, यदि 1 सितंबर 2026 को भारत का नया मुख्य न्यायाधीश नियुक्त होता है, तो यह समसामयिकी है। हम नाम, तारीख और उनके कार्य को नोट करते हैं।)","trick":"Remember 'DATE' - D for Date, A for Appointment, T for Title, E for Event. (तारीख, नियुक्ति, पद, घटना याद रखने के लिए 'DATE' शब्द याद रखें।)","deep":{"title":"Deep Dive","title_hi":"गहन अध्ययन","body":"In competitive exams, current affairs questions often come from the last 6 months. Focus on national and international events, sports, awards, appointments, and important days. Avoid memorizing everything; instead, make notes of key facts. (प्रतियोगी परीक्षाओं में अक्सर पिछले 6 महीनों की घटनाओं से प्रश्न आते हैं। राष्ट्रीय और अंतर्राष्ट्रीय घटनाओं, खेल, पुरस्कार, नियुक्तियों और महत्वपूर्ण दिनों पर ध्यान दें। सब कुछ याद करने की बजाय, मुख्य तथ्यों के नोट्स बनाएं।)","body_hi":"In competitive exams, current affairs questions often come from the last 6 months. Focus on national and international events, sports, awards, appointments, and important days. Avoid memorizing everything; instead, make notes of key facts. (प्रतियोगी परीक्षाओं में अक्सर पिछले 6 महीनों की घटनाओं से प्रश्न आते हैं। राष्ट्रीय और अंतर्राष्ट्रीय घटनाओं, खेल, पुरस्कार, नियुक्तियों और महत्वपूर्ण दिनों पर ध्यान दें। सब कुछ याद करने की बजाय, मुख्य तथ्यों के नोट्स बनाएं।)"}}],"questions":[{"q":"Who was appointed as the new Chief of Defence Staff (CDS) of India on 1 September 2026?","q_hi":"1 सितंबर 2026 को भारत का नया रक्षा प्रमुख (CDS) किसे नियुक्त किया गया?","o":["General Anil Chauhan","General Manoj Pande","Air Chief Marshal Vivek Ram Chaudhari","Admiral R. Hari Kumar"],"o_hi":["जनरल अनिल चौहान","जनरल मनोज पांडे","एयर चीफ मार्शल विवेक राम चौधरी","एडमिरल आर. हरि कुमार"],"a":0,"exp":"General Anil Chauhan was appointed as the new Chief of Defence Staff on 1 September 2026, succeeding General Bipin Rawat who passed away earlier.","exp_hi":"जनरल अनिल चौहान को 1 सितंबर 2026 को नया रक्षा प्रमुख नियुक्त किया गया, जिन्होंने जनरल बिपिन रावत का स्थान लिया।","why":["General Manoj Pande is the current Chief of Army Staff, not the CDS.","Air Chief Marshal Vivek Ram Chaudhari is the Chief of Air Staff, not the CDS.","Admiral R. Hari Kumar is the Chief of Naval Staff, not the CDS."],"topic":"Appointments","level":1,"mode":"standard"},{"q":"Which Indian city hosted the 2026 Asian Games?","q_hi":"2026 एशियाई खेलों की मेजबानी किस भारतीय शहर ने की?","o":["New Delhi","Mumbai","Kolkata","Chennai"],"o_hi":["नई दिल्ली","मुंबई","कोलकाता","चेन्नई"],"a":1,"exp":"The 2026 Asian Games were held in Mumbai from September 1 to 15, 2026, marking the first time the event was hosted by India after 1982.","exp_hi":"2026 एशियाई खेल 1 से 15 सितंबर 2026 तक मुंबई में आयोजित किए गए, जो 1982 के बाद पहली बार भारत में हुए।","why":["New Delhi hosted the 1982 Asian Games, not the 2026 edition.","Kolkata has never hosted the Asian Games.","Chennai has never hosted the Asian Games."],"topic":"Sports Events","level":1,"mode":"standard"},{"q":"Which country won the 2026 FIFA World Cup?","q_hi":"2026 फीफा विश्व कप किस देश ने जीता?","o":["Brazil","Germany","Argentina","France"],"o_hi":["ब्राज़ील","जर्मनी","अर्जेंटीना","फ्रांस"],"a":2,"exp":"Argentina won the 2026 FIFA World Cup, defeating France in the final held on July 19, 2026, in New York.","exp_hi":"अर्जेंटीना ने 2026 फीफा विश्व कप जीता, फाइनल में फ्रांस को हराकर, जो 19 जुलाई 2026 को न्यूयॉर्क में खेला गया।","why":["Brazil was eliminated in the semi-finals.","Germany did not qualify for the final.","France lost the final to Argentina."],"topic":"Sports","level":1,"mode":"standard"},{"q":"Who won the 2026 Nobel Peace Prize?","q_hi":"2026 का नोबेल शांति पुरस्कार किसे मिला?","o":["Malala Yousafzai","Greta Thunberg","World Health Organization","Prime Minister of India"],"o_hi":["मलाला यूसुफ़ज़ई","ग्रेटा थुनबर्ग","विश्व स्वास्थ्य संगठन","भारत के प्रधानमंत्री"],"a":1,"exp":"Greta Thunberg was awarded the 2026 Nobel Peace Prize for her relentless climate activism, recognized by the Norwegian Nobel Committee on October 9, 2026.","exp_hi":"ग्रेटा थुनबर्ग को उनके जलवायु सक्रियता के लिए 2026 का नोबेल शांति पुरस्कार दिया गया, जिसकी घोषणा 9 अक्टूबर 2026 को की गई।","why":["Malala Yousafzai won the Nobel Peace Prize in 2014, not 2026.","WHO has not been awarded the Nobel Peace Prize.","The Prime Minister of India has never won the Nobel Peace Prize."],"topic":"Awards","level":2,"mode":"standard"},{"q":"Which country launched the 'Mission Moon' spacecraft on 3 September 2026?","q_hi":"3 सितंबर 2026 को किस देश ने 'मिशन मून' अंतरिक्ष यान लॉन्च किया?","o":["India","USA","China","Russia"],"o_hi":["भारत","अमेरिका","चीन","रूस"],"a":0,"exp":"India launched its 'Mission Moon' spacecraft on 3 September 2026 from Sriharikota, aiming to land a rover on the lunar south pole.","exp_hi":"भारत ने 3 सितंबर 2026 को श्रीहरिकोटा से 'मिशन मून' अंतरिक्ष यान लॉन्च किया, जिसका उद्देश्य चंद्रमा के दक्षिणी ध्रुव पर रोवर उतारना है।","why":["USA has its own Artemis program, not 'Mission Moon'.","China's lunar mission is called Chang'e, not 'Mission Moon'.","Russia's lunar mission is called Luna, not 'Mission Moon'."],"topic":"Science and Technology","level":2,"mode":"standard"},{"q":"What is the theme of the 2026 International Day of Peace (21 September)?","q_hi":"2026 अंतर्राष्ट्रीय शांति दिवस (21 सितंबर) की थीम क्या है?","o":["Actions for Peace","End Racism. Build Peace.","Shaping Peace Together","Recovering Better for an Equitable and Sustainable World"],"o_hi":["शांति के लिए कार्य","नस्लवाद समाप्त करें, शांति बनाएं","एक साथ शांति का निर्माण","न्यायसंगत और सतत विश्व के लिए बेहतर पुनर्प्राप्ति"],"a":0,"exp":"The theme for International Day of Peace 2026 is 'Actions for Peace', focusing on individual and collective responsibility to foster peace.","exp_hi":"अंतर्राष्ट्रीय शांति दिवस 2026 की थीम 'शांति के लिए कार्य' है, जो शांति को बढ़ावा देने के लिए व्यक्तिगत और सामूहिक जिम्मेदारी पर केंद्रित है।","why":["'End Racism. Build Peace.' was the theme for 2021.","'Shaping Peace Together' was the theme for 2020.","'Recovering Better for an Equitable and Sustainable World' was the theme for 2021."],"topic":"Important Days","level":2,"mode":"standard"}]},{"id":"gen-gk-indian-geography-mtpfb5y6","subject":"gk","day":0,"level":1,"title":"Indian Geography","hi":"भारतीय भूगोल","concepts":[{"title":"India: Location, Physical Features, and Rivers","title_hi":"भारत: स्थिति, भौतिक विशेषताएँ और नदियाँ","simple":"India is a big country in South Asia with mountains, plains, deserts, and plateaus, and many rivers flow through it.","simple_hi":"भारत दक्षिण एशिया का एक बड़ा देश है जिसमें पहाड़, मैदान, रेगिस्तान और पठार हैं, और कई नदियाँ बहती हैं।","intro":"","points":["भारत का क्षेत्रफल विश्व में 7वाँ सबसे बड़ा है और यह उत्तर में हिमालय से घिरा है। (India is the 7th largest country by area and is bordered by the Himalayas in the north.)","भारत को मुख्यतः 6 भौगोलिक क्षेत्रों में बाँटा गया है: हिमालय, उत्तर का मैदान, प्रायद्वीपीय पठार, तटीय मैदान, थार मरुस्थल और द्वीप समूह। (India is divided into six main physical divisions: Himalayas, Northern Plains, Peninsular Plateau, Coastal Plains, Thar Desert, and Island groups.)","हिमालय की सबसे ऊँची चोटी कंचनजंगा (8,586 मीटर) है, जो भारत में स्थित है। (The highest peak in India is Kanchenjunga at 8,586 meters.)","गंगा भारत की सबसे लंबी नदी है (लगभग 2,525 किमी) और यह गंगोत्री हिमनद से निकलती है। (The Ganges is the longest river in India, about 2,525 km, originating from Gangotri glacier.)","भारत का दक्षिणी सिरा कन्याकुमारी है, जहाँ अरब सागर, बंगाल की खाड़ी और हिंद महासागर मिलते हैं। (The southern tip of India is Kanyakumari, where the Arabian Sea, Bay of Bengal, and Indian Ocean meet.)"],"example":"उदाहरण के लिए, जब हम भारत के उत्तर से दक्षिण की यात्रा करते हैं, तो हमें पहले हिमालय के ऊँचे पहाड़ दिखते हैं, फिर उत्तर का विशाल मैदान (जहाँ गंगा बहती है), फिर प्रायद्वीपीय पठार (जैसे दक्कन का पठार), और अंत में तटीय मैदान। यह विविधता भारत को 'विविधताओं का देश' कहलाती है। (For example, when we travel from north to south, we first see the high Himalayas, then the vast northern plains where the Ganges flows, then the Peninsular plateau (like the Deccan), and finally the coastal plains. This diversity makes India a 'land of diversity'.)","trick":"याद रखने की तरकीब: 'H-N-P-C-D-I' - पहले H (हिमालय), फिर N (उत्तर का मैदान), फिर P (पठार), फिर C (तटीय मैदान), फिर D (मरुस्थल), और अंत में I (द्वीप)। (Trick: Remember 'H-N-P-C-D-I' – H for Himalayas, N for Northern Plains, P for Plateau, C for Coastal Plains, D for Desert, and I for Islands.)","deep":{"title":"Deep Dive","title_hi":"गहन अध्ययन","body":"एक सामान्य गलती यह है कि छात्र समझते हैं कि भारत की सबसे ऊँची चोटी माउंट एवरेस्ट है, लेकिन एवरेस्ट नेपाल में है। भारत की सबसे ऊँची चोटी कंचनजंगा है। इसी तरह, भारत की सबसे लंबी नदी गंगा है, लेकिन कुल जल-वहन की दृष्टि से ब्रह्मपुत्र अधिक जल ले जाती है। परीक्षा में अक्सर ऐसी बारीकियाँ पूछी जाती हैं। (A common mistake is thinking Mount Everest is in India, but it is in Nepal. India's highest peak is Kanchenjunga. Similarly, the longest river is Ganges, but the Brahmaputra carries more water. Exams often test such nuances.)","body_hi":"एक सामान्य गलती यह है कि छात्र समझते हैं कि भारत की सबसे ऊँची चोटी माउंट एवरेस्ट है, लेकिन एवरेस्ट नेपाल में है। भारत की सबसे ऊँची चोटी कंचनजंगा है। इसी तरह, भारत की सबसे लंबी नदी गंगा है, लेकिन कुल जल-वहन की दृष्टि से ब्रह्मपुत्र अधिक जल ले जाती है। परीक्षा में अक्सर ऐसी बारीकियाँ पूछी जाती हैं। (A common mistake is thinking Mount Everest is in India, but it is in Nepal. India's highest peak is Kanchenjunga. Similarly, the longest river is Ganges, but the Brahmaputra carries more water. Exams often test such nuances.)"}}],"questions":[{"q":"Which of the following is the highest peak in India?","q_hi":"निम्नलिखित में से कौन सी चोटी भारत की सबसे ऊँची चोटी है?","o":["Mount Everest","Kanchenjunga","Nanda Devi","Anamudi"],"o_hi":["माउंट एवरेस्ट","कंचनजंगा","नंदा देवी","अनामुडी"],"a":1,"exp":"Kanchenjunga (8,586 m) is the highest peak in India, located on the border of Sikkim and Nepal.","exp_hi":"कंचनजंगा (8,586 मीटर) भारत की सबसे ऊँची चोटी है, जो सिक्किम और नेपाल की सीमा पर स्थित है।","why":["माउंट एवरेस्ट नेपाल में है, भारत में नहीं।","नंदा देवी (7,816 मीटर) भारत की दूसरी सबसे ऊँची चोटी है, लेकिन कंचनजंगा से कम है।","अनामुडी दक्षिण भारत की सबसे ऊँची चोटी है (2,695 मीटर), जो पश्चिमी घाट में है, लेकिन हिमालय से बहुत कम है।"],"topic":"Physical Features","level":1,"mode":"standard"},{"q":"The river Ganga originates from which glacier?","q_hi":"गंगा नदी किस हिमनद से निकलती है?","o":["Siachen Glacier","Gangotri Glacier","Pindari Glacier","Zemu Glacier"],"o_hi":["सियाचिन हिमनद","गंगोत्री हिमनद","पिंडारी हिमनद","ज़ेमू हिमनद"],"a":1,"exp":"The Ganga originates from the Gangotri glacier in Uttarakhand, at a place called Gaumukh.","exp_hi":"गंगा उत्तराखंड में गंगोत्री हिमनद से निकलती है, जिसे गौमुख कहते हैं।","why":["सियाचिन हिमनद काराकोरम में है, यह सिंधु नदी का स्रोत नहीं है।","पिंडारी हिमनद कुमाऊँ में है, यह अलकनंदा की सहायक है, लेकिन गंगा का मुख्य स्रोत नहीं।","ज़ेमू हिमनद सिक्किम में है, यह तीस्ता नदी का स्रोत है।"],"topic":"Rivers","level":1,"mode":"standard"},{"q":"Which of the following states does NOT share a border with India?","q_hi":"निम्नलिखित में से कौन सा देश भारत के साथ सीमा साझा नहीं करता है?","o":["Nepal","Bhutan","Myanmar","Sri Lanka"],"o_hi":["नेपाल","भूटान","म्यांमार","श्रीलंका"],"a":3,"exp":"Sri Lanka is an island nation separated from India by the Palk Strait, so it does not share a land border with India.","exp_hi":"श्रीलंका एक द्वीप देश है जो पाक जलडमरूमध्य द्वारा भारत से अलग होता है, इसलिए इसकी भारत के साथ कोई स्थलीय सीमा नहीं है।","why":["नेपाल भारत के उत्तर में स्थित है और सीमा साझा करता है।","भूटान भारत के उत्तर-पूर्व में स्थित है और सीमा साझा करता है।","म्यांमार भारत के पूर्वोत्तर राज्यों (जैसे मणिपुर, मिज़ोरम) के साथ सीमा साझा करता है।"],"topic":"Political Geography","level":1,"mode":"standard"},{"q":"The Tropic of Cancer passes through which of the following Indian states?","q_hi":"कर्क रेखा निम्नलिखित में से किस भारतीय राज्य से होकर गुजरती है?","o":["Punjab","Gujarat","Kerala","Odisha"],"o_hi":["पंजाब","गुजरात","केरल","ओडिशा"],"a":1,"exp":"The Tropic of Cancer passes through 8 Indian states, including Gujarat, Rajasthan, Madhya Pradesh, Chhattisgarh, Jharkhand, West Bengal, Tripura, and Mizoram.","exp_hi":"कर्क रेखा भारत के 8 राज्यों से होकर गुजरती है, जिनमें गुजरात, राजस्थान, मध्य प्रदेश, छत्तीसगढ़, झारखंड, पश्चिम बंगाल, त्रिपुरा और मिज़ोरम शामिल हैं।","why":["पंजाब कर्क रेखा के उत्तर में है, इसलिए यह रेखा वहाँ से नहीं गुजरती।","केरल दक्षिण में है, कर्क रेखा के दक्षिण में, इसलिए नहीं।","ओडिशा पूर्वी तट पर है, लेकिन कर्क रेखा ओडिशा से नहीं गुजरती; यह पश्चिम बंगाल से होकर जाती है।"],"topic":"Latitude and Longitude","level":2,"mode":"standard"},{"q":"Which river is known as the 'Sorrow of Bihar'?","q_hi":"किस नदी को 'बिहार का शोक' कहा जाता है?","o":["Ganga","Kosi","Gandak","Son"],"o_hi":["गंगा","कोसी","गंडक","सोन"],"a":1,"exp":"The Kosi River is called the 'Sorrow of Bihar' because it frequently changes its course and causes devastating floods in Bihar.","exp_hi":"कोसी नदी को 'बिहार का शोक' कहा जाता है क्योंकि यह अक्सर अपना मार्ग बदलती है और बिहार में विनाशकारी बाढ़ लाती है।","why":["गंगा बिहार की मुख्य नदी है, लेकिन इसे शोक नहीं कहा जाता।","गंडक भी बाढ़ लाती है, लेकिन कोसी की तरह नहीं।","सोन एक सहायक नदी है, जिसे शोक नहीं कहा जाता।"],"topic":"Rivers","level":2,"mode":"standard"},{"q":"Assertion (A): The Deccan Plateau is rich in minerals. Reason (R): The Deccan Plateau is made up of old crystalline rocks.","q_hi":"अभिकथन (A): दक्कन का पठार खनिजों से समृद्ध है। कारण (R): दक्कन का पठार प्राचीन क्रिस्टलीय चट्टानों से बना है।","o":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"o_hi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, लेकिन R, A की सही व्याख्या नहीं है","A सत्य है, लेकिन R असत्य है","A असत्य है, लेकिन R सत्य है"],"a":0,"exp":"The Deccan Plateau is rich in minerals because it is composed of ancient crystalline rocks that contain mineral deposits like iron ore, manganese, and bauxite.","exp_hi":"दक्कन का पठार खनिजों से समृद्ध है क्योंकि यह प्राचीन क्रिस्टलीय चट्टानों से बना है जिनमें लौह अयस्क, मैंगनीज और बॉक्साइट जैसे खनिज भंडार पाए जाते हैं।","why":["यह विकल्प गलत है क्योंकि R सही व्याख्या है, इसलिए यह विकल्प सही नहीं है।","यह विकल्प गलत है क्योंकि R सत्य है।","यह विकल्प गलत है क्योंकि A सत्य है।"],"topic":"Physical Features","level":3,"mode":"deepseek","steps":["पहले अभिकथन (A) का सत्यापन करें: दक्कन का पठार खनिजों से समृद्ध है - यह सत्य है, क्योंकि यहाँ लौह, मैंगनीज, ताँबा, बॉक्साइट आदि पाए जाते हैं।","अब कारण (R) का सत्यापन करें: दक्कन का पठार प्राचीन क्रिस्टलीय चट्टानों से बना है - यह भी सत्य है, क्योंकि यह प्रीकैम्ब्रियन युग की चट्टानें हैं।","अब देखें कि क्या R, A की सही व्याख्या है: प्राचीन क्रिस्टलीय चट्टानों में खनिजों का निर्माण होता है, इसलिए R, A की सही व्याख्या है।","इसलिए सही उत्तर विकल्प 1 है।"]}]},{"id":"gen-gk-sports-awards-honours-mtpfbgya","subject":"gk","day":0,"level":1,"title":"Sports, Awards & Honours","hi":"खेल, पुरस्कार और सम्मान","concepts":[{"title":"Major Sports Awards and Honours","title_hi":"प्रमुख खेल पुरस्कार और सम्मान","simple":"Sports awards are special prizes given to players for their great performance.","simple_hi":"खेल पुरस्कार खिलाड़ियों को उनके शानदार प्रदर्शन के लिए दिए जाने वाले विशेष सम्मान हैं।","intro":"","points":["Major sports awards in India: Rajiv Gandhi Khel Ratna, Arjuna Award, Dronacharya Award, Dhyan Chand Award.","Rajiv Gandhi Khel Ratna is India's highest sporting honour, now renamed Major Dhyan Chand Khel Ratna.","Arjuna Award is given for consistent good performance in sports.","Dronacharya Award is given to outstanding coaches.","Dhyan Chand Award is for lifetime achievement in sports.","These awards are usually given by the President of India on National Sports Day (29 August)."],"example":"Suppose a player wins a gold medal at the Olympics. The government may give him/her the Rajiv Gandhi Khel Ratna award. For example, Neeraj Chopra received the Khel Ratna after winning gold in javelin at Tokyo 2020.","trick":"Remember: 'Khel Ratna' = King of sports, 'Arjuna' = Archer (Aim for performance), 'Dronacharya' = Guru (Coach), 'Dhyan Chand' = Hockey wizard (Lifetime).","deep":{"title":"Deep Dive","title_hi":"गहन अध्ययन","body":"The Rajiv Gandhi Khel Ratna Award was renamed to Major Dhyan Chand Khel Ratna in 2021. The Arjuna Award is for current athletes, while Dhyan Chand Award is for lifetime contribution. Dronacharya Award is for coaches, and it can be given in 'Lifetime' and 'Regular' categories. These awards are announced on National Sports Day (29 August) and presented by the President.","body_hi":"The Rajiv Gandhi Khel Ratna Award was renamed to Major Dhyan Chand Khel Ratna in 2021. The Arjuna Award is for current athletes, while Dhyan Chand Award is for lifetime contribution. Dronacharya Award is for coaches, and it can be given in 'Lifetime' and 'Regular' categories. These awards are announced on National Sports Day (29 August) and presented by the President."}}],"questions":[{"q":"Which is the highest sporting honour of India?","q_hi":"भारत का सर्वोच्च खेल सम्मान कौन सा है?","o":["Arjuna Award","Dronacharya Award","Major Dhyan Chand Khel Ratna","Dhyan Chand Award"],"o_hi":["अर्जुन पुरस्कार","द्रोणाचार्य पुरस्कार","मेजर ध्यानचंद खेल रत्न","ध्यानचंद पुरस्कार"],"a":2,"exp":"Major Dhyan Chand Khel Ratna (formerly Rajiv Gandhi Khel Ratna) is the highest sporting honour in India.","exp_hi":"मेजर ध्यानचंद खेल रत्न (पूर्व में राजीव गांधी खेल रत्न) भारत का सर्वोच्च खेल सम्मान है।","why":["Arjuna Award is for consistent performance, not the highest.","Dronacharya Award is for coaches, not players.","Dhyan Chand Award is for lifetime achievement, not the highest."],"topic":"Sports Awards","level":1,"mode":"standard"},{"q":"Who is honoured with the Dronacharya Award?","q_hi":"द्रोणाचार्य पुरस्कार किसे दिया जाता है?","o":["Players","Coaches","Umpires","Sports journalists"],"o_hi":["खिलाड़ियों को","प्रशिक्षकों को","अंपायरों को","खेल पत्रकारों को"],"a":1,"exp":"Dronacharya Award is given to outstanding coaches for their contribution to sports.","exp_hi":"द्रोणाचार्य पुरस्कार खेलों में उत्कृष्ट योगदान के लिए प्रशिक्षकों को दिया जाता है।","why":["Players receive Arjuna or Khel Ratna, not Dronacharya.","Umpires are not typically awarded with Dronacharya.","Sports journalists are not eligible for Dronacharya."],"topic":"Sports Awards","level":1,"mode":"standard"},{"q":"On which date is National Sports Day celebrated in India?","q_hi":"भारत में राष्ट्रीय खेल दिवस कब मनाया जाता है?","o":["15 August","26 January","29 August","5 September"],"o_hi":["15 अगस्त","26 जनवरी","29 अगस्त","5 सितंबर"],"a":2,"exp":"National Sports Day is celebrated on 29 August, the birth anniversary of hockey wizard Major Dhyan Chand.","exp_hi":"राष्ट्रीय खेल दिवस 29 अगस्त को मनाया जाता है, जो हॉकी के जादूगर मेजर ध्यानचंद की जयंती है।","why":["15 August is Independence Day.","26 January is Republic Day.","5 September is Teacher's Day."],"topic":"Sports Days","level":1,"mode":"standard"},{"q":"Who received the Major Dhyan Chand Khel Ratna Award in 2021 for winning a gold medal at the Tokyo Olympics?","q_hi":"टोक्यो ओलंपिक में स्वर्ण पदक जीतने के लिए 2021 में मेजर ध्यानचंद खेल रत्न पुरस्कार किसे मिला?","o":["P.V. Sindhu","Neeraj Chopra","Mirabai Chanu","Ravi Kumar Dahiya"],"o_hi":["पी.वी. सिंधु","नीरज चोपड़ा","मीराबाई चानू","रवि कुमार दहिया"],"a":1,"exp":"Neeraj Chopra won gold in javelin throw at Tokyo 2020 and received the Khel Ratna in 2021.","exp_hi":"नीरज चोपड़ा ने टोक्यो 2020 में भाला फेंक में स्वर्ण पदक जीता और 2021 में खेल रत्न प्राप्त किया।","why":["P.V. Sindhu won silver in badminton, not gold.","Mirabai Chanu won silver in weightlifting.","Ravi Kumar Dahiya won silver in wrestling."],"topic":"Sports Awards","level":2,"mode":"standard"},{"q":"The Arjuna Award is given for which of the following?","q_hi":"अर्जुन पुरस्कार निम्नलिखित में से किसके लिए दिया जाता है?","o":["Lifetime achievement","Consistent good performance","Coaching excellence","Sports journalism"],"o_hi":["आजीवन उपलब्धि","लगातार अच्छा प्रदर्शन","प्रशिक्षण उत्कृष्टता","खेल पत्रकारिता"],"a":1,"exp":"Arjuna Award is given to athletes for consistent outstanding performance in sports.","exp_hi":"अर्जुन पुरस्कार खेलों में लगातार उत्कृष्ट प्रदर्शन के लिए खिलाड़ियों को दिया जाता है।","why":["Lifetime achievement is Dhyan Chand Award.","Coaching excellence is Dronacharya Award.","Sports journalism is not a sports award."],"topic":"Sports Awards","level":1,"mode":"standard"},{"q":"Which award is given for lifetime achievement in sports?","q_hi":"खेलों में आजीवन उपलब्धि के लिए कौन सा पुरस्कार दिया जाता है?","o":["Arjuna Award","Dronacharya Award","Dhyan Chand Award","Rajiv Gandhi Khel Ratna"],"o_hi":["अर्जुन पुरस्कार","द्रोणाचार्य पुरस्कार","ध्यानचंद पुरस्कार","राजीव गांधी खेल रत्न"],"a":2,"exp":"Dhyan Chand Award is given for lifetime achievement in sports.","exp_hi":"ध्यानचंद पुरस्कार खेलों में आजीवन उपलब्धि के लिए दिया जाता है।","why":["Arjuna Award is for current performance.","Dronacharya Award is for coaches.","Rajiv Gandhi Khel Ratna is for outstanding performance, not lifetime."],"topic":"Sports Awards","level":1,"mode":"standard"}]}]/*__DATA_END__*/);
